export interface LiveTrainErrorClassification {
  isQuotaLimit: boolean;
  message: string;
}

/**
 * Classifies live train fetch errors so quota exhaustion (HTTP 403 / limit_exceeded)
 * triggers LimitReachedModal instead of raw error strings or noisy console errors,
 * while genuine server/network/account_blocked errors remain clearly distinguishable.
 */
interface HttpErrorShape {
  code?: string;
  message?: string;
  response?: {
    status?: number;
    data?: {
      error?: string;
      message?: string;
    };
  };
}

export function classifyLiveTrainFetchError(err: unknown, offlineText: string, isOnline: boolean = true): LiveTrainErrorClassification {
  const httpErr = (err && typeof err === 'object' ? err : {}) as HttpErrorShape;
  const status = httpErr.response?.status;
  const errData = httpErr.response?.data;
  const errCode = typeof errData?.error === 'string' ? errData.error : '';

  if (errCode === 'limit_exceeded' || (status === 403 && errCode !== 'account_blocked')) {
    return {
      isQuotaLimit: true,
      message: typeof errData?.message === 'string' && errData.message.trim()
        ? errData.message.trim()
        : 'Daily free live tracking limit reached. Sign in, watch an ad, or upgrade to PRO to continue.',
    };
  }

  if (!isOnline) {
    return { isQuotaLimit: false, message: offlineText };
  }

  if (httpErr.code === 'ERR_NETWORK' || (typeof httpErr.message === 'string' && httpErr.message.includes('Network Error'))) {
    return {
      isQuotaLimit: false,
      message: 'Cannot connect to backend server. Please verify your connection.',
    };
  }

  if (typeof errData?.message === 'string' && errData.message.trim()) {
    return { isQuotaLimit: false, message: errData.message.trim() };
  }

  if (errCode && errCode !== 'limit_exceeded') {
    return { isQuotaLimit: false, message: errCode };
  }

  return {
    isQuotaLimit: false,
    message: typeof httpErr.message === 'string' && httpErr.message.trim() ? httpErr.message : 'Failed to fetch live status.',
  };
}

