/* ─── helpers ─────────────────────────────────────────────────────────────── */
const delayColor = (mins: number, statusSummary?: string, isRunning?: boolean, isFuture?: boolean) => {
  const summary = (statusSummary || '').toLowerCase();
  if (summary.includes('cancel')) {
    return { text: "text-rose-400", bg: "bg-rose-500/10 border-rose-500/20", label: "Cancelled" };
  }
  if (isFuture || summary.includes('scheduled')) {
    return { text: "text-blue-400", bg: "bg-blue-500/10 border-blue-500/20", label: "Scheduled" };
  }
  if (summary.includes('reached destination') || summary.includes('completed')) {
    if (mins > 0) {
      return { text: "text-amber-400", bg: "bg-amber-500/10 border-amber-500/20", label: `Completed (+${mins}m)` };
    }
    return { text: "text-slate-400", bg: "bg-slate-500/10 border-slate-500/20", label: "Completed" };
  }
  if (summary.includes('yet to start')) {
    if (mins > 0) {
      return { text: "text-amber-400", bg: "bg-amber-500/10 border-amber-500/20", label: `Yet to start (+${mins}m)` };
    }
    return { text: "text-blue-400", bg: "bg-blue-500/10 border-blue-500/20", label: "Yet to start" };
  }
  if (!mins || mins <= 0) {
    return { text: "text-emerald-400", bg: "bg-emerald-500/10 border-emerald-500/20", label: "On Time" };
  }
  if (mins <= 15) return { text: "text-yellow-400", bg: "bg-yellow-500/10 border-yellow-500/20", label: `+${mins} min` };
  if (mins <= 60) return { text: "text-orange-400", bg: "bg-orange-500/10 border-orange-500/20", label: `+${mins} min` };
  return { text: "text-red-400", bg: "bg-red-500/10 border-red-500/20", label: `+${Math.floor(mins / 60)}h ${mins % 60}m` };
};

/* ─── smooth lerp between two lat/lngs ───────────────────────────────────── */
function lerp(a: number, b: number, t: number) { return a + (b - a) * t; }

/* ─── Map (client-only, smoothly animates marker) ────────────────────────── */
function LiveMap({ position, stationName }: { position: LatLng; stationName: string }) {
  const mapRef = useRef<any>(null);
  const markerRef = useRef<any>(null);
  const divRef = useRef<HTMLDivElement>(null);
  const currentPos = useRef<LatLng>(position);
  const targetPos = useRef<LatLng>(position);
  const rafRef = useRef<number>(0);
  const leafletRef = useRef<any>(null);

  // Smooth animation loop: lerp currentPos → targetPos every frame
  const animateMarker = useCallback(() => {
    if (!markerRef.current) return;
    const cur = currentPos.current;
    const tgt = targetPos.current;
    const SPEED = 0.03; // 0 to 1, lower = smoother

    const newLat = lerp(cur.lat, tgt.lat, SPEED);
    const newLng = lerp(cur.lng, tgt.lng, SPEED);
    currentPos.current = { lat: newLat, lng: newLng };

    const dist = Math.abs(tgt.lat - newLat) + Math.abs(tgt.lng - newLng);
    if (dist > 0.00001) {
      markerRef.current.setLatLng([newLat, newLng]);
      rafRef.current = requestAnimationFrame(animateMarker);
    } else {
      markerRef.current.setLatLng([tgt.lat, tgt.lng]);
      currentPos.current = tgt;
    }
  }, []);

  // Init map once
  useEffect(() => {
    if (!divRef.current || typeof window === "undefined") return;

    import("leaflet").then((L) => {
      leafletRef.current = L;
      delete (L.Icon.Default.prototype as any)._getIconUrl;
      L.Icon.Default.mergeOptions({
        iconRetinaUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png",
        iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
        shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
      });

      if (!mapRef.current) {
        mapRef.current = L.map(divRef.current!, { zoomControl: true, scrollWheelZoom: true })
          .setView([position.lat, position.lng], 11);

        L.tileLayer("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png", {
          attribution: '&copy; <a href="https://carto.com/">CARTO</a>',
          subdomains: "abcd", maxZoom: 19,
        }).addTo(mapRef.current);
      }

      const pulsingIcon = L.divIcon({
        className: "",
        html: `
          <div style="position:relative;width:44px;height:44px">
            <div style="position:absolute;inset:0;border-radius:50%;background:rgba(37,99,235,0.25);animation:railpulse 1.8s ease-out infinite"></div>
            <div style="position:absolute;inset:4px;border-radius:50%;background:rgba(37,99,235,0.15);animation:railpulse 1.8s ease-out 0.4s infinite"></div>
            <div style="position:absolute;inset:10px;border-radius:50%;background:#2563eb"></div>
            <div style="position:absolute;inset:18px;border-radius:50%;background:white"></div>
          </div>
          <style>
            @keyframes railpulse {
              0%   { transform:scale(1);   opacity:.7 }
              100% { transform:scale(2.2); opacity:0  }
            }
          </style>
        `,
        iconSize: [44, 44], iconAnchor: [22, 22],
      });

      markerRef.current = L.marker([position.lat, position.lng], { icon: pulsingIcon })
        .addTo(mapRef.current)
        .bindPopup(`<b>🚆 ${stationName}</b><br>Current Position`)
        .openPopup();

      currentPos.current = position;
      targetPos.current = position;
    });

    return () => {
      cancelAnimationFrame(rafRef.current);
      if (mapRef.current) { mapRef.current.remove(); mapRef.current = null; markerRef.current = null; }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Animate to new position whenever `position` prop changes
  useEffect(() => {
    if (!markerRef.current) return;
    cancelAnimationFrame(rafRef.current);
    targetPos.current = position;

    // Pan map smoothly to new center
    if (mapRef.current) {
      mapRef.current.panTo([position.lat, position.lng], { animate: true, duration: 1.5 });
    }

    rafRef.current = requestAnimationFrame(animateMarker);
    return () => cancelAnimationFrame(rafRef.current);
  }, [position, animateMarker]);

  return (
    <div className="relative w-full h-72 md:h-96 rounded-2xl overflow-hidden border border-subtle">
      <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />
      <div ref={divRef} className="w-full h-full" />
      <div className="absolute top-3 left-3 z-[1000] bg-card/90 backdrop-blur-sm border border-subtle rounded-xl px-3 py-1.5 flex items-center gap-2">
        <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
        <span className="text-xs font-bold text-blue-500 dark:text-blue-400">LIVE POSITION</span>
      </div>
    </div>
  );
}

/* ─── "X seconds ago" ticker ─────────────────────────────────────────────── */
function SecondsTicker({ since }: { since: Date }) {
  const [secs, setSecs] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setSecs(Math.floor((Date.now() - since.getTime()) / 1000)), 1000);
    return () => clearInterval(id);
  }, [since]);

  const label = secs < 60 ? `${secs}s ago` : `${Math.floor(secs / 60)}m ago`;
  const color = secs < 15 ? "text-emerald-400" : secs < 60 ? "text-yellow-400" : "text-orange-400";

  return (
    <span className={`font-mono text-xs ${color} tabular-nums`}>
      Last updated: {label}
    </span>
  );
}

/* ─── Progress tracker ────────────────────────────────────────────────────── */
function ProgressTracker({ source, current, destination, timeline }: {
  source: string; current: string; destination: string; timeline: TimelineStop[];
}) {
  const totalStops = Math.max(timeline.length, 3);
  const completedIdx = timeline.findIndex(s => s.status === "current");
  const lastDist = timeline.length > 0 ? timeline[timeline.length - 1]?.distance : null;
  const curDist = completedIdx >= 0 ? timeline[completedIdx]?.distance : null;
  const rawPct =
    lastDist && Number(lastDist) > 0 && curDist !== null && curDist !== undefined && Number(curDist) >= 0
      ? Math.round((Number(curDist) / Number(lastDist)) * 100)
      : completedIdx >= 0 && totalStops > 1
      ? Math.round((completedIdx / (totalStops - 1)) * 100)
      : 0;
  const pct = Math.max(0, Math.min(100, rawPct));

  return (
    <div className="bg-card border border-subtle rounded-2xl p-6">
      <h3 className="text-xs font-bold text-muted uppercase tracking-widest mb-5 flex items-center gap-2">
        <Navigation className="w-3.5 h-3.5 text-blue-500 dark:text-blue-400" />
        Journey Progress
      </h3>
      <div className="relative mb-6">
        <div className="h-2 bg-card rounded-full overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-blue-600 to-blue-400 rounded-full transition-[width] duration-[1500ms] ease-in-out"
            style={{ width: `${pct}%` }}
          />
        </div>
        <div className="absolute left-0 -top-1.5 w-5 h-5 rounded-full bg-emerald-500 border-2 border-card" />
        <div
          className="absolute -top-2 w-6 h-6 rounded-full bg-blue-600 border-2 border-card shadow-md flex items-center justify-center transition-[left] duration-[1500ms] ease-in-out z-10"
          style={{ left: `calc(${pct}% - 12px)` }}>
          <span className="absolute -inset-1 rounded-full bg-blue-500/30 animate-ping" />
          <TrainFront className="w-3 h-3 text-white relative z-10" />
        </div>
        <div className="absolute right-0 -top-1.5 w-5 h-5 rounded-full bg-slate-600 border-2 border-card" />
      </div>
      <div className="flex justify-between text-xs">
        <div className="text-left">
          <div className="font-bold text-emerald-400">{source}</div>
          <div className="text-muted text-[10px]">Origin</div>
        </div>
        <div className="text-center">
          <div className="font-bold text-blue-500 dark:text-blue-400">{current}</div>
          <div className="text-muted text-[10px]">Current</div>
        </div>
        <div className="text-right">
          <div className="font-bold text-muted">{destination}</div>
          <div className="text-muted text-[10px]">Destination</div>
        </div>
      </div>
      <div className="mt-4 text-right text-xs text-muted">{pct}% of journey completed</div>
    </div>
  );
}

