/* ─── Speed Gauge ─────────────────────────────────────────────────────────── */
function SpeedGauge({ speed }: { speed: number | null }) {
  const isAvailable = speed !== null && speed !== undefined;
  const kmh = isAvailable ? speed : 0;
  const maxKmh = 160;
  const pct = isAvailable ? Math.min(kmh / maxKmh, 1) : 0;

  const statusInfo = (() => {
    if (!isAvailable) return { label: "Speed unavailable", color: "text-muted", ring: "bg-slate-500", arcColor: "#475569", glow: "" };
    if (kmh === 0) return { label: "Stopped", color: "text-muted", ring: "bg-slate-500", arcColor: "#475569", glow: "" };
    if (kmh < 40) return { label: "Slow", color: "text-amber-400", ring: "bg-amber-400", arcColor: "#f59e0b", glow: "shadow-amber-500/20" };
    if (kmh < 90) return { label: "Moderate", color: "text-blue-400", ring: "bg-blue-400", arcColor: "#60a5fa", glow: "shadow-blue-500/20" };
    return { label: "Fast ⚡", color: "text-emerald-400", ring: "bg-emerald-400", arcColor: "#34d399", glow: "shadow-emerald-500/30" };
  })();

  const radius = 44;
  const cx = 60;
  const cy = 60;
  const totalLen = Math.PI * radius;
  const arcLen = pct * totalLen;

  return (
    <div className={`bg-card border border-subtle rounded-2xl p-5 flex flex-col items-center gap-2 shadow-lg ${statusInfo.glow}`}>
      <div className="flex items-center gap-2 self-start mb-1">
        <Gauge className="w-3.5 h-3.5 text-rose-400" />
        <span className="text-[10px] text-muted font-bold uppercase tracking-wider">Speed</span>
      </div>

      {/* SVG half-circle arc gauge */}
      <div className="relative">
        <svg width="120" height="68" viewBox="0 0 120 68">
          {/* Track */}
          <path
            d={`M ${cx - radius} ${cy} A ${radius} ${radius} 0 0 1 ${cx + radius} ${cy}`}
            fill="none" stroke="currentColor" className="text-subtle/20" strokeWidth="8" strokeLinecap="round"
          />
          {/* Filled arc */}
          <path
            d={`M ${cx - radius} ${cy} A ${radius} ${radius} 0 0 1 ${cx + radius} ${cy}`}
            fill="none"
            stroke={statusInfo.arcColor}
            strokeWidth="8" strokeLinecap="round"
            strokeDasharray={`${arcLen} ${totalLen}`}
            style={{ transition: "stroke-dasharray 1.2s ease-in-out, stroke 0.6s ease" }}
          />
        </svg>
        {/* Value overlay */}
        <div className="absolute inset-0 flex flex-col items-center justify-end pb-2">
          <span className={`text-2xl font-black tabular-nums leading-none ${statusInfo.color}`}>{isAvailable ? kmh : "--"}</span>
          <span className="text-[10px] text-muted font-bold">{isAvailable ? "km/h" : "N/A"}</span>
        </div>
      </div>

      {/* Status badge */}
      <div className="flex items-center gap-2 mt-1">
        <div className="relative flex items-center justify-center">
          {isAvailable && kmh > 0 && (
            <span className={`absolute w-3 h-3 rounded-full ${statusInfo.ring} opacity-40 animate-ping`} />
          )}
          <span className={`w-2.5 h-2.5 rounded-full ${statusInfo.ring} relative`} />
        </div>
        <span className={`text-xs font-extrabold tracking-wider ${statusInfo.color}`}>{statusInfo.label}</span>
      </div>
    </div>
  );
}


/* ─── Main page ───────────────────────────────────────────────────────────── */
export default function LiveTrainClient() {
  const getIstDateString = (offsetDays: number = 0): string => {
    const now = new Date();
    const utcMs = now.getTime() + now.getTimezoneOffset() * 60000;
    const targetMs = utcMs + 5.5 * 3600000 + offsetDays * 86400000;
    const dateObj = new Date(targetMs);
    const yyyy = dateObj.getFullYear();
    const mm = String(dateObj.getMonth() + 1).padStart(2, '0');
    const dd = String(dateObj.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  };

  const getIstDateLabel = (offsetDays: number = 0): string => {
    const now = new Date();
    const utcMs = now.getTime() + now.getTimezoneOffset() * 60000;
    const targetMs = utcMs + 5.5 * 3600000 + offsetDays * 86400000;
    const dateObj = new Date(targetMs);
    return dateObj.toLocaleDateString('en-IN', { day: 'numeric', month: 'short' });
  };

  const params = useParams();
  const router = useRouter();
  const searchParams = useSearchParams();
  const urlMode = searchParams ? searchParams.get('mode') : null;
  const rawParam = params?.trainNo;
  const trainNo = Array.isArray(rawParam) ? rawParam[0] : rawParam ?? "";

  const [insideMode, setInsideMode] = useState(urlMode === 'inside');
  const gps = useDeviceGPS(insideMode);

  useEffect(() => {
    if (urlMode === 'inside') {
      setInsideMode(true);
    }
  }, [urlMode]);

  const [data, setData] = useState<LiveData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showLimitModal, setShowLimitModal] = useState(false);
  const [quotaBlocked, setQuotaBlocked] = useState(false);
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [showAllStops, setShowAllStops] = useState(false);
  const [showPastStops, setShowPastStops] = useState(false);
  const [expandedPassThrough, setExpandedPassThrough] = useState<Record<string, boolean>>({});
  const [showJumpFab, setShowJumpFab] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const [voiceLang, setVoiceLang] = useState<'hi' | 'en'>('hi');
  const [voiceGender, setVoiceGender] = useState<'female' | 'male'>('female');
  const [isVoicePlaying, setIsVoicePlaying] = useState(false);

  // Stop voice playback on component unmount
  useEffect(() => {
    return () => {
      voiceService.stop();
    };
  }, []);

  const playLiveVoice = (langToUse: 'hi' | 'en' = voiceLang, genderToUse: 'female' | 'male' = voiceGender) => {
    if (!data) return;

    setIsVoicePlaying(true);
    voiceService.speakLiveTrackingStatus(
      {
        trainNo: data.trainNo || trainNo,
        trainName: data.trainName,
        statusMessage: data.statusSummary,
        currentStation: data.currentStation,
        nextStation: data.nextStation,
        delayMinutes: data.delay,
        destinationStation: data.destination,
        speed: data.speed,
      },
      langToUse,
      genderToUse,
      () => {
        setIsVoicePlaying(false);
      }
    );
  };

  const handleToggleVoice = () => {
    if (isVoicePlaying) {
      voiceService.stop();
      setIsVoicePlaying(false);
      return;
    }
    playLiveVoice(voiceLang, voiceGender);
  };

  const handleSelectVoiceLang = (newLang: 'hi' | 'en') => {
    setVoiceLang(newLang);
    voiceService.setLanguage(newLang);
    const wasPlaying = isVoicePlaying;
    voiceService.stop();
    setIsVoicePlaying(false);
    if (wasPlaying) {
      setTimeout(() => playLiveVoice(newLang, voiceGender), 250);
    }
  };

  const handleSelectVoiceGender = (newGender: 'female' | 'male') => {
    setVoiceGender(newGender);
    voiceService.setGender(newGender);
    const wasPlaying = isVoicePlaying;
    voiceService.stop();
    setIsVoicePlaying(false);
    if (wasPlaying) {
      setTimeout(() => playLiveVoice(voiceLang, newGender), 250);
    }
  };
  const { t } = useLanguage();
  const [selectedDate, setSelectedDate] = useState<string>(() => getIstDateString(0));
  const [hasSelectedDateManually, setHasSelectedDateManually] = useState(false);
  const selectedDateRef = useRef(selectedDate);
  useEffect(() => {
    selectedDateRef.current = selectedDate;
  }, [selectedDate]);

  const lastScrolledTrainRef = useRef<string | null>(null);

  // Auto-scroll to current station stop ONLY on initial train load (never on polling/refresh updates)
  useEffect(() => {
    if (data?.trainNo && lastScrolledTrainRef.current !== data.trainNo) {
      lastScrolledTrainRef.current = data.trainNo;
      const timer = setTimeout(() => {
        const el = document.getElementById('current-train-stop');
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 250);
      return () => clearTimeout(timer);
    }
  }, [data?.trainNo]);

  // Stable position ref to smooth between fetches
  const prevPosition = useRef<LatLng | null>(null);
  const [mapPosition, setMapPosition] = useState<LatLng | null>(null);

  const fetchLive = useCallback(async (silent = false, targetDate = selectedDate) => {
    if (!trainNo) return;
    if (!silent) setLoading(true);
    else setRefreshing(true);
    setError(null);
    setQuotaBlocked(false);

    if (typeof navigator !== 'undefined' && !navigator.onLine) {
      if (!silent) setError(t('offline_desc'));
      setLoading(false);
      setRefreshing(false);
      return;
    }

    try {
      const res = await axios.get(`${API_BASE}/trains/live/${trainNo}`, {
        params: { date: targetDate },
        headers: buildAuthHeaders(),
        timeout: 15000
      });
      const raw = res.data?.data || res.data;

      const rawTimeline = raw.journey_timeline || raw.timeline || raw.stations || [];
      const normalizedTimeline: TimelineStop[] = rawTimeline.map((s: any) => {
        const renderTime = (timeVal: any): string => {
          if (!timeVal) return '--:--';
          if (typeof timeVal === 'string') return timeVal;
          if (typeof timeVal === 'object') {
            return timeVal.scheduled || timeVal.time || timeVal.actual || '--:--';
          }
          return '--:--';
        };

        const statusMapped = (() => {
          const st = (s.status || '').toLowerCase();
          if (st === 'departed' || st === 'completed') return 'completed';
          if (st === 'current') return 'current';
          return 'upcoming';
        })();

        const stopCoords =
          s.coordinates?.lat != null && s.coordinates?.lon != null
            ? { lat: Number(s.coordinates.lat), lon: Number(s.coordinates.lon) }
            : s.lat != null && s.lng != null
            ? { lat: Number(s.lat), lon: Number(s.lng) }
            : null;

        return {
          station: s.station_name || s.station || s.stationName || 'Station',
          code: s.station_code || s.code || s.stationCode || '--',
          arrival: renderTime(s.arrival_time || s.arrival || s.arrivalTime),
          departure: renderTime(s.departure_time || s.departure || s.departureTime),
          status: statusMapped,
          station_type: s.station_type ?? undefined,
          platform: s.platform || s.platform_number || s.platform_no || null,
          distance: s.distance !== undefined && s.distance !== null ? Number(s.distance) : null,
          delay_minutes: Number(s.delay_minutes ?? raw.delay_minutes ?? raw.delay ?? 0),
          is_halt: s.is_halt !== undefined ? Boolean(s.is_halt) : true,
          coordinates: stopCoords,
        };
      });

      const currentStopCoords =
        normalizedTimeline.find((s) => s.status === 'current')?.coordinates ||
        normalizedTimeline.find((s) => s.coordinates !== null && s.coordinates !== undefined)?.coordinates ||
        null;

      const latRaw = raw.latitude ?? raw.train_location?.lat ?? raw.lat ?? currentStopCoords?.lat ?? null;
      const lngRaw = raw.longitude ?? raw.train_location?.lon ?? raw.lng ?? currentStopCoords?.lon ?? null;
      const lat = latRaw !== null && Number.isFinite(Number(latRaw)) ? Number(latRaw) : null;
      const lng = lngRaw !== null && Number.isFinite(Number(lngRaw)) ? Number(lngRaw) : null;

      const resolvedSource =
        (raw.source && raw.source !== '--' ? raw.source : '') ||
        (raw.from && raw.from !== '--' ? raw.from : '') ||
        normalizedTimeline[0]?.station ||
        "--";
      const resolvedDestination =
        (raw.destination && raw.destination !== '--' ? raw.destination : '') ||
        (raw.to && raw.to !== '--' ? raw.to : '') ||
        normalizedTimeline[normalizedTimeline.length - 1]?.station ||
        "--";

      const normalized: LiveData = {
        trainName: raw.train_name || raw.trainName || raw.trainInfo?.train_name || raw.trainInfo?.trainName || `Train ${trainNo}`,
        trainNo: raw.train_number || raw.trainNo || trainNo,
        currentStation: raw.current_station || raw.currentStation || "Unknown",
        nextStation:    raw.next_station    || raw.nextStation    || "--",
        delay:          raw.delay_minutes   || raw.delay          || 0,
        lastUpdated:    raw.last_updated    || raw.lastUpdated    || new Date().toISOString(),
        lat, lng,
        speed:          raw.speed           ?? null,
        source:         resolvedSource,
        destination:    resolvedDestination,
        timeline:       normalizedTimeline,
        activeJourneyDate: raw.activeJourneyDate || raw.active_journey_date || null,
        statusSummary: raw.status_summary || raw.statusSummary || raw.statusNote || raw.status || '',
        isRunning: raw.is_running ?? raw.isRunning ?? true,
        isCancelled: raw.is_cancelled || raw.isCancelled || false,
        coaches: raw.coaches || [],
        rakeType: raw.rake_type || raw.rakeType || null,
        totalCoaches: raw.total_coaches || (raw.coaches ? raw.coaches.length : 0),
      };

      setData((prev) => {
        const coaches = (raw.coaches && raw.coaches.length > 0)
          ? raw.coaches
          : (prev?.coaches && prev.coaches.length > 0 ? prev.coaches : []);
        const rakeType = raw.rake_type || raw.rakeType || prev?.rakeType || null;
        const totalCoaches = raw.total_coaches || (coaches.length > 0 ? coaches.length : prev?.totalCoaches || 0);

        return {
          ...normalized,
          coaches,
          rakeType,
          totalCoaches,
        };
      });
      const now = new Date();
      setLastRefresh(now);

      let announceStr = `Live status updated for ${normalized.trainName}. `;
      announceStr += `Currently at ${normalized.currentStation}. `;
      if (normalized.speed !== null) {
        announceStr += `Speed is ${normalized.speed} kilometers per hour. `;
      }
      if (normalized.delay > 0) {
        announceStr += `Delay is ${normalized.delay} minutes.`;
      } else {
        announceStr += `On time.`;
      }
      setAnnouncement(announceStr);

      // Smoothly update map position
      if (lat !== null && lng !== null) {
        const newPos = { lat, lng };
        if (!prevPosition.current) {
          prevPosition.current = newPos;
          setMapPosition(newPos);
        } else {
          prevPosition.current = newPos;
          setMapPosition(newPos); // LiveMap will animate
        }
      }
    } catch (err: any) {
      const isOnline = typeof navigator === 'undefined' ? true : navigator.onLine;
      const classified = classifyLiveTrainFetchError(err, t('offline_desc'), isOnline);

      if (classified.isQuotaLimit) {
        if (!silent) {
          setQuotaBlocked(true);
          setShowLimitModal(true);
          setError(null);
        }
        setAnnouncement('Daily live tracking limit reached.');
      } else {
        console.error("LIVE ERROR:", err);
        if (!silent) setError(classified.message);
        setAnnouncement(`Failed to update status: ${classified.message}`);
      }
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [trainNo, t, selectedDate]);

  // Auto-fetch when selectedDate changes (manually clicked or auto-detected)
  useEffect(() => {
    if (trainNo && selectedDate) {
      fetchLive(false, selectedDate);
    }
  }, [selectedDate, trainNo, fetchLive]);

  // 30-second auto-refresh
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (trainNo) {
      interval = setInterval(() => {
        fetchLive(true, selectedDateRef.current);
      }, 30000);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [trainNo, fetchLive]);

  // Hide floating Jump FAB when current stop card is visible on screen (prevents mobile header overlap)
  useEffect(() => {
    if (typeof window === 'undefined' || !data?.timeline?.length) {
      setShowJumpFab(false);
      return;
    }
    const targetEl = document.getElementById('current-train-stop');
    if (!targetEl || typeof IntersectionObserver === 'undefined') {
      setShowJumpFab(true);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[0];
        if (entry) setShowJumpFab(!entry.isIntersecting);
      },
      { threshold: 0.15 }
    );
    observer.observe(targetEl);
    return () => observer.disconnect();
  }, [data?.trainNo, data?.timeline?.length, showPastStops, showAllStops]);

  const dc = data ? delayColor(data.delay, data.statusSummary, data.isRunning, selectedDate > getIstDateString(0)) : null;

  return (
    <div className="min-h-screen bg-app text-main px-4 py-8 md:px-8 max-w-5xl mx-auto">
      <div className="sr-only" aria-live="polite" role="status">
        {announcement}
      </div>

      {/* ── Header ── */}
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => router.back()}
          className="p-2 rounded-xl bg-input hover:bg-card border border-subtle transition-colors"
          aria-label="Go back">
          <ArrowLeft className="w-5 h-5 text-muted" />
        </button>
        <div>
          <div className="flex items-center gap-2 flex-wrap">
            <div className="p-1.5 rounded-lg bg-blue-500/10">
              <TrainFront className="w-5 h-5 text-blue-500 dark:text-blue-400" />
            </div>
            <h1 className="text-2xl font-extrabold text-main tracking-tight">
              {data?.trainName || `Train ${trainNo}`}
            </h1>
            <span className="text-xs font-mono text-muted bg-input px-2 py-0.5 rounded border border-subtle">
              #{data?.trainNo || trainNo}
            </span>
          </div>
          <div className="flex items-center gap-3 mt-1 flex-wrap">
            <div className="flex items-center gap-1.5 text-xs text-muted">
              <Radio className="w-3 h-3 text-emerald-400 animate-pulse" />
              Live Tracking
            </div>
            {lastRefresh && <SecondsTicker since={lastRefresh} />}
          </div>
        </div>

        {/* Bilingual Voice Announcement Controls */}
        {data && (
          <div className="flex items-center gap-2 flex-wrap ml-auto">
            {/* Language Switch */}
            <div className="flex items-center gap-1 bg-input/80 p-0.5 rounded-xl border border-subtle text-[11px]" role="group" aria-label="Select Voice Announcement Language">
              <button
                type="button"
                onClick={() => handleSelectVoiceLang('hi')}
                aria-pressed={voiceLang === 'hi'}
                className={clsx(
                  "min-h-[36px] px-2.5 py-1 rounded-lg font-bold transition-all cursor-pointer touch-manipulation",
                  voiceLang === 'hi' ? "bg-primary text-white shadow-xs" : "text-muted hover:text-main"
                )}
              >
                🇮🇳 हिंदी
              </button>
              <button
                type="button"
                onClick={() => handleSelectVoiceLang('en')}
                aria-pressed={voiceLang === 'en'}
                className={clsx(
                  "min-h-[36px] px-2.5 py-1 rounded-lg font-bold transition-all cursor-pointer touch-manipulation",
                  voiceLang === 'en' ? "bg-primary text-white shadow-xs" : "text-muted hover:text-main"
                )}
              >
                🌐 English
              </button>
            </div>

            {/* Persona Switch: Priya vs Rohan */}
            <div className="flex items-center gap-1 bg-input/80 p-0.5 rounded-xl border border-subtle text-[11px]" role="group" aria-label="Select Voice Announcer Persona">
              <button
                type="button"
                onClick={() => handleSelectVoiceGender('female')}
                aria-pressed={voiceGender === 'female'}
                title="Priya - Railway Announcer (रेलवे उद्घोषक)"
                className={clsx(
                  "min-h-[36px] px-2.5 py-1 rounded-lg font-bold transition-all cursor-pointer touch-manipulation flex items-center gap-1",
                  voiceGender === 'female' ? "bg-primary text-white shadow-xs" : "text-muted hover:text-main"
                )}
              >
                <span>👩</span>
                <span>Priya</span>
              </button>
              <button
                type="button"
                onClick={() => handleSelectVoiceGender('male')}
                aria-pressed={voiceGender === 'male'}
                title="Rohan - Station Master (स्टेशन मास्टर)"
                className={clsx(
                  "min-h-[36px] px-2.5 py-1 rounded-lg font-bold transition-all cursor-pointer touch-manipulation flex items-center gap-1",
                  voiceGender === 'male' ? "bg-primary text-white shadow-xs" : "text-muted hover:text-main"
                )}
              >
                <span>👨</span>
                <span>Rohan</span>
              </button>
            </div>

            {/* Listen Button */}
            <button
              type="button"
              onClick={handleToggleVoice}
              aria-label={isVoicePlaying ? "Stop voice announcement" : "Listen to live train status announcement"}
              aria-pressed={isVoicePlaying}
              className={clsx(
                "min-h-[44px] min-w-[44px] px-3.5 py-2 rounded-xl text-xs font-bold transition-all border flex items-center gap-2 cursor-pointer active:scale-95 touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500",
                isVoicePlaying
                  ? "bg-blue-600 text-white border-blue-400 animate-pulse shadow-md font-black"
                  : "bg-blue-500/10 hover:bg-blue-500/20 text-blue-500 border-blue-500/30 hover:border-blue-500/50"
              )}
            >
              {isVoicePlaying ? (
                <>
                  <Square size={14} className="fill-current text-white" />
                  <span>{voiceLang === 'hi' ? 'रुकिए' : 'Stop'}</span>
                  <div className="flex items-center gap-0.5 ml-1" aria-hidden="true">
                    <span className="w-0.5 h-3 bg-white rounded-full animate-bounce [animation-delay:-0.3s]" />
                    <span className="w-0.5 h-4 bg-white rounded-full animate-bounce [animation-delay:-0.15s]" />
                    <span className="w-0.5 h-2 bg-white rounded-full animate-bounce" />
                  </div>
                </>
              ) : (
                <>
                  <Volume2 size={16} />
                  <span>{voiceLang === 'hi' ? 'स्थिति सुनें' : 'Listen Status'}</span>
                </>
              )}
            </button>
          </div>
        )}

        <button onClick={() => fetchLive(true, selectedDateRef.current)} disabled={refreshing}
          className="ml-auto p-2 rounded-xl bg-blue-500/10 hover:bg-blue-500/20 border border-blue-500/20 transition-colors disabled:opacity-50"
          aria-label="Refresh live train status"
          title="Refresh">
          <RefreshCw className={`w-4 h-4 text-blue-500 dark:text-blue-400 ${refreshing ? "animate-spin" : ""}`} />
        </button>
      </div>

      {/* ── Loading ── */}
      {loading && <Skeleton />}

      {/* ── Quota Limit State (if modal closed without unlocking) ── */}
      {!loading && quotaBlocked && !error && !data && (
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-amber-500/10 border border-amber-500/25 rounded-2xl p-5">
          <div className="flex items-start gap-3">
            <Zap className="w-5 h-5 text-amber-500 mt-0.5 shrink-0" />
            <div>
              <div className="font-bold text-main text-sm">Daily free live tracking limit reached</div>
              <div className="text-xs text-muted mt-1">
                Sign in, watch a short ad, or upgrade to PRO to unlock live tracking for Train #{trainNo}.
              </div>
            </div>
          </div>
          <button
            type="button"
            onClick={() => setShowLimitModal(true)}
            className="px-4 py-2 rounded-xl bg-primary hover:brightness-110 text-white text-xs font-bold shrink-0 cursor-pointer transition-all"
          >
            Unlock Live Status
          </button>
        </div>
      )}

      {/* ── Error ── */}
      {!loading && error && (
        <div className="flex items-start gap-3 bg-red-500/10 border border-red-500/20 rounded-2xl p-5">
          <AlertCircle className="w-5 h-5 text-red-400 mt-0.5 shrink-0" />
          <div>
            <div className="font-bold text-red-400 text-sm">Live status unavailable</div>
            <div className="text-xs text-muted mt-1">{error}</div>
          </div>
        </div>
      )}

      {/* ── Data ── */}
      {!loading && data && (
        <div className="space-y-6">

          {/* Date Selector Tabs */}
          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-none">
            {(() => {
              const tabs = [
                { offset: -2, label: '2 Days Ago', desc: getIstDateLabel(-2) },
                { offset: -1, label: 'Yesterday', desc: getIstDateLabel(-1) },
                { offset: 0, label: 'Today', desc: getIstDateLabel(0) }
              ];

              const activeDate = data?.activeJourneyDate;
              if (activeDate === getIstDateString(-3)) {
                tabs.unshift({ offset: -3, label: '3 Days Ago', desc: getIstDateLabel(-3) });
              }

              return tabs.map((item) => {
                const dateVal = getIstDateString(item.offset);
                const isSelected = selectedDate === dateVal;
                const isActiveRun = activeDate === dateVal;
                return (
                  <button
                    key={item.offset}
                    type="button"
                    onClick={() => {
                      setHasSelectedDateManually(true);
                      setSelectedDate(dateVal);
                    }}
                    className={`px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-wider transition-all border flex items-center gap-1.5 shrink-0 ${isSelected
                      ? "bg-blue-600 border-blue-500 text-white shadow-md shadow-blue-500/20"
                      : "bg-input border-subtle text-muted hover:text-main hover:bg-strong"
                      }`}
                  >
                    <span>{item.label} <span className="opacity-70 font-bold">({item.desc})</span></span>
                    {isActiveRun && (
                      <span className="inline-flex items-center gap-1 bg-emerald-500/20 text-emerald-400 px-1.5 py-0.5 rounded text-[8px] font-black uppercase tracking-wider animate-pulse">
                        ● Active
                      </span>
                    )}
                  </button>
                );
              });
            })()}
          </div>

          {/* Mode Selector Tabs: Outside vs Inside (Live Speed) */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div className="flex bg-input/60 dark:bg-slate-900/60 p-1 rounded-2xl border border-subtle min-h-[40px] items-center shadow-xs self-start">
              <button 
                type="button"
                onClick={() => setInsideMode(false)}
                className={clsx(
                  "flex items-center gap-1.5 px-3.5 py-1.5 text-xs font-bold rounded-xl transition-all touch-manipulation cursor-pointer",
                  !insideMode ? 'bg-blue-600 text-white shadow-xs' : 'text-secondary hover:text-main'
                )}
              >
                <TrainFront className="w-3.5 h-3.5" />
                <span>Outside (Schedule)</span>
              </button>
              <button 
                type="button"
                onClick={() => setInsideMode(true)}
                className={clsx(
                  "flex items-center gap-1.5 px-3.5 py-1.5 text-xs font-bold rounded-xl transition-all touch-manipulation cursor-pointer",
                  insideMode ? 'bg-emerald-600 text-white shadow-xs' : 'text-secondary hover:text-emerald-500'
                )}
              >
                <Gauge className="w-3.5 h-3.5" />
                <span>Inside (Live Speed)</span>
                {insideMode && <span className="w-1.5 h-1.5 rounded-full bg-emerald-300 animate-ping" />}
              </button>
            </div>
          </div>

          {/* ── ONBOARD GPS SPEEDOMETER PROMPT (Outside Mode) ── */}
          {!insideMode && (
            <div className="p-4 rounded-2xl bg-gradient-to-r from-blue-500/10 via-indigo-500/10 to-emerald-500/10 border border-blue-500/25 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 shadow-xs">
              <div className="flex items-center gap-3">
                <div className="p-2.5 rounded-xl bg-blue-500/15 text-blue-500 dark:text-blue-400 shrink-0">
                  <Gauge className="w-5 h-5 animate-pulse" />
                </div>
                <div>
                  <h4 className="text-xs font-bold text-main uppercase tracking-wider flex items-center gap-2">
                    Travelling Inside Train #{data.trainNo || trainNo}?
                    <span className="text-[9px] px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 font-black">GPS READY</span>
                  </h4>
                  <p className="text-xs text-muted mt-0.5">
                    Check live train speed (km/h), moving/stopped status, and real-time carriage speed using your device GPS.
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setInsideMode(true)}
                className="w-full sm:w-auto px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs shadow-md transition-all flex items-center justify-center gap-2 cursor-pointer shrink-0 active:scale-95"
              >
                <Gauge className="w-4 h-4" />
                <span>Open Live Speedometer</span>
              </button>
            </div>
          )}

          {/* ── MOTION-GRAPHIC GPS SPEEDOMETER GAUGE (Inside Mode) ── */}
          {insideMode && (
            <div className="space-y-6 animate-in fade-in duration-300">
              <TrainSpeedometerGauge
                speed={gps.speed}
                moving={gps.moving}
                heading={gps.heading}
                accuracy={gps.accuracy}
                maxSpeed={gps.maxSpeed}
                permissionGranted={gps.permissionGranted}
                error={gps.error}
                trainNo={data.trainNo || trainNo}
                trainName={data.trainName}
                onClose={() => setInsideMode(false)}
              />
            </div>
          )}

          {/* Stat cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="col-span-2 md:col-span-1 bg-card border border-subtle rounded-2xl p-5">
              <div className="flex items-center gap-2 mb-2">
                <MapPin className="w-3.5 h-3.5 text-blue-500 dark:text-blue-400" />
                <span className="text-[10px] text-muted font-bold uppercase tracking-wider">Current Station</span>
              </div>
              <div className="font-extrabold text-main text-lg leading-tight">{data.currentStation}</div>
            </div>

            <div className="bg-card border border-subtle rounded-2xl p-5">
              <div className="flex items-center gap-2 mb-2">
                <Navigation className="w-3.5 h-3.5 text-blue-400" />
                <span className="text-[10px] text-muted font-bold uppercase tracking-wider">Next Stop</span>
              </div>
              <div className="font-extrabold text-main text-base leading-tight">{data.nextStation}</div>
            </div>

            <div className={`bg-card border border-subtle rounded-2xl p-5 ${dc?.bg}`}>
              <div className="flex items-center gap-2 mb-2">
                <Clock className={`w-3.5 h-3.5 ${dc?.text}`} />
                <span className="text-[10px] text-muted font-bold uppercase tracking-wider">Delay</span>
              </div>
              <div className={`font-extrabold text-lg ${dc?.text}`}>{dc?.label}</div>
              {data.delay > 0 && <div className="text-[10px] text-muted mt-1">{data.delay} minutes late</div>}
            </div>

            {/* Speed Gauge */}
            <SpeedGauge speed={data.speed} />
          </div>

          {/* Map */}
          {mapPosition ? (
            <div className="relative w-full h-72 md:h-96 rounded-2xl overflow-hidden border border-subtle">
              <DynamicMap position={mapPosition} stationName={data.currentStation} />
              <div className="absolute top-3 left-3 z-[1000] bg-card/90 backdrop-blur-sm border border-subtle rounded-xl px-3 py-1.5 flex items-center gap-2 pointer-events-none">
                <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
                <span className="text-xs font-bold text-blue-500 dark:text-blue-400">LIVE POSITION</span>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-48 bg-card border border-subtle rounded-2xl gap-3">
              <MapPin className="w-8 h-8 text-muted" />
              <p className="text-muted text-sm">GPS coordinates not available for this train</p>
            </div>
          )}

          {/* Progress */}
          <ProgressTracker
            source={data.source}
            current={data.currentStation}
            destination={data.destination}
            timeline={data.timeline}
          />

          {/* Coach Composition */}
          {data.coaches && data.coaches.length > 0 && (
            <CoachVisualizer
              coaches={data.coaches}
              rakeType={data.rakeType}
              totalCoaches={data.totalCoaches || data.coaches.length}
              trainNo={data.trainNo || trainNo}
              trainName={data.trainName}
            />
          )}

          {/* Station Proximity Wake-Up Alarm */}
          {data.timeline && data.timeline.length > 0 && (
            <div className="mb-4">
              <StationAlarm
                trainNo={data.trainNo || trainNo}
                destinationCode={data.timeline[data.timeline.length - 1]?.code}
                destinationName={data.timeline[data.timeline.length - 1]?.station || 'Destination Station'}
                showLanguageToggle={false}
                stations={data.timeline}
              />
            </div>
          )}

          {/* Timeline */}
          {data.timeline.length > 0 && (
            <div className="bg-card border border-subtle rounded-2xl p-6">
              <div className="flex items-center justify-between gap-2 mb-5 flex-wrap">
                <h3 className="text-xs font-bold text-muted uppercase tracking-widest flex items-center gap-2">
                  <Clock className="w-3.5 h-3.5 text-blue-500 dark:text-blue-400" />
                  Journey Timeline
                </h3>
                <div className="flex items-center gap-2 ml-auto">
                  <button
                    type="button"
                    onClick={() => {
                      const el = document.getElementById('current-train-stop');
                      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    }}
                    className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-blue-500/10 hover:bg-blue-500/20 text-blue-600 dark:text-blue-400 border border-blue-500/25 text-[10px] font-bold transition-colors cursor-pointer"
                  >
                    <Navigation size={11} />
                    <span>Current Stop</span>
                  </button>
                  <span className="text-[10px] text-muted font-normal normal-case">
                    {showAllStops
                      ? data.timeline.length
                      : data.timeline.filter(s => s.station_type !== 'MINOR_STATION').length
                    } of {data.timeline.length} stops
                  </span>
                </div>
              </div>
              <div className="relative">
                <div className="absolute left-[19px] top-2 bottom-2 w-0.5 bg-card" />

                {(() => {
                  const filteredStops = data.timeline.filter(stop =>
                    showAllStops ||
                    stop.station_type !== 'MINOR_STATION' ||
                    stop.status === 'current'
                  );
                  const currentIdx = filteredStops.findIndex(s => s.status === 'current');
                  const pastStops = currentIdx > 0 ? filteredStops.slice(0, currentIdx) : [];
                  const activeStops = currentIdx >= 0 ? filteredStops.slice(currentIdx) : filteredStops;
                  const delayVal = Number(data?.delay ?? 0);

                  const renderStop = (stop: TimelineStop, i: number) => {
                    const isCur = stop.status === "current";
                    const isDone = stop.status === "completed";
                    const isNextStop = !isDone && !isCur && ((currentIdx >= 0 && i === currentIdx + 1) || (currentIdx < 0 && i === 0));
                    const isUpcoming = !isDone && !isCur;
                    const eta = isUpcoming && delayVal > 0 ? addMinutesToTime(stop.arrival, delayVal) : null;
                    const etd = isUpcoming && delayVal > 0 ? addMinutesToTime(stop.departure, delayVal) : null;
                    const etaDiffers = Boolean(eta && eta !== 'Unknown' && stop.arrival !== '--:--' && eta !== stop.arrival);
                    const etdDiffers = Boolean(etd && etd !== 'Unknown' && stop.departure !== '--:--' && etd !== stop.departure);
                    const haltMins = getHaltTime(stop.arrival, stop.departure);

                    return (
                      <div
                        key={i}
                        id={isCur ? "current-train-stop" : undefined}
                        role="listitem"
                        aria-label={`Station ${stop.station} (${stop.code || ""}). Status: ${stop.status}. Arrival: ${stop.arrival || "none"}, Departure: ${stop.departure || "none"}`}
                        className={clsx(
                          "relative flex items-start gap-4 py-3.5 pl-3 pr-4 rounded-2xl transition-all overflow-hidden backdrop-blur-xs",
                          isCur
                            ? "bg-blue-500/[0.08] dark:bg-blue-950/40 border-2 border-blue-500 dark:border-blue-400 shadow-lg shadow-blue-500/15 ring-2 ring-blue-500/20"
                            : isNextStop
                              ? "bg-amber-500/5 dark:bg-amber-950/20 border border-amber-500/30 shadow-xs"
                              : isDone
                                ? "opacity-75 border border-transparent hover:opacity-100 hover:bg-input/20"
                                : "border border-transparent hover:bg-card/40"
                        )}
                      >
                        <div className={`relative z-10 mt-0.5 w-7 h-7 rounded-full border-2 flex items-center justify-center shrink-0 ${isDone ? "bg-emerald-500/20 border-emerald-500/40 text-emerald-600 dark:text-emerald-400 shadow-xs" :
                          isCur ? "bg-gradient-to-tr from-blue-600 to-indigo-600 border-white dark:border-slate-900 text-white shadow-[0_0_15px_rgba(37,99,235,0.7)] scale-110" :
                            isNextStop ? "bg-amber-500 border-white dark:border-slate-900 text-white shadow-xs" :
                              "bg-card border-strong text-muted"
                          }`}>
                          {isCur && <span className="absolute -inset-2.5 rounded-full bg-blue-500/25 animate-ping pointer-events-none" />}
                          {isCur && <span className="absolute -inset-1 rounded-full bg-blue-500/35 animate-pulse blur-xs pointer-events-none" />}
                          {isDone && <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />}
                          {isCur && <TrainFront className="w-4 h-4 text-white relative z-10 animate-pulse" />}
                          {isNextStop && <Navigation className="w-3 h-3 text-white" />}
                        </div>
                        <div className="flex-1 min-w-0 relative z-10">
                          <div className={`font-semibold text-sm flex flex-wrap items-center gap-1.5 ${isCur ? "text-blue-600 dark:text-blue-400 font-black" : isNextStop ? "text-amber-600 dark:text-amber-400 font-bold" : isDone ? "text-muted" : "text-main"}`}>
                            <span>{stop.station}</span>
                            {stop.code && <span className="text-[10px] text-muted font-mono font-bold">({stop.code})</span>}
                            {stop.platform && (
                              <span className="text-[10px] font-mono font-bold text-main bg-input/70 px-1.5 py-0.5 rounded border border-subtle">
                                PF {stop.platform}
                              </span>
                            )}
                            {stop.distance !== null && stop.distance !== undefined && (
                              <span className="text-[10px] font-mono text-muted bg-input/40 px-1.5 py-0.5 rounded border border-subtle/60">
                                {Math.round(stop.distance)} km
                              </span>
                            )}
                            {haltMins > 0 && (
                              <span className="text-[9px] font-medium text-muted bg-input/40 px-1.5 py-0.5 rounded border border-subtle/60">
                                Halt: {haltMins}m
                              </span>
                            )}
                            {stop.station_type === 'MAJOR_JUNCTION' && (
                              <span className="text-[9px] font-black text-amber-500 bg-amber-500/10 px-1 py-0.5 rounded uppercase tracking-wider border border-amber-500/20">JN</span>
                            )}
                            {stop.station_type === 'TERMINAL' && (
                              <span className="text-[9px] font-black text-blue-500 bg-blue-500/10 px-1 py-0.5 rounded uppercase tracking-wider border border-blue-500/20">TERMINAL</span>
                            )}
                            {isCur && (
                              <span className="inline-flex items-center gap-1.5 text-[10px] font-black text-white bg-gradient-to-r from-blue-600 to-indigo-600 px-2.5 py-0.5 rounded-full uppercase tracking-wider shadow-md shadow-blue-500/30 animate-pulse">
                                <span className="w-1.5 h-1.5 rounded-full bg-white animate-ping" />
                                <TrainFront size={11} /> CURRENT STATION
                              </span>
                            )}
                            {isNextStop && (
                              <span className="inline-flex items-center gap-1 text-[10px] font-bold text-amber-700 dark:text-amber-400 bg-amber-500/20 px-2 py-0.5 rounded-full uppercase tracking-wider border border-amber-500/30">
                                <Navigation size={10} /> NEXT STOP
                              </span>
                            )}
                            {isDone && (
                              <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-wider">
                                PASSED
                              </span>
                            )}
                          </div>
                          <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1">
                            {stop.arrival && (
                              <span className={`text-[11px] font-mono ${isCur || isNextStop ? "text-main font-semibold" : "text-muted"}`}>
                                {isDone ? "Act Arr: " : isUpcoming ? "ETA: " : "Arr: "}
                                <span className={etaDiffers ? "text-orange-600 dark:text-amber-400 font-bold" : ""}>
                                  {etaDiffers ? eta : stop.arrival}
                                </span>
                                {etaDiffers && (
                                  <span className="ml-1 text-[9px] text-muted line-through">sch {stop.arrival}</span>
                                )}
                              </span>
                            )}
                            {stop.departure && (
                              <span className={`text-[11px] font-mono ${isCur || isNextStop ? "text-main font-semibold" : "text-muted"}`}>
                                {isDone ? "Act Dep: " : isUpcoming ? "ETD: " : "Dep: "}
                                <span className={etdDiffers ? "text-orange-600 dark:text-amber-400 font-bold" : ""}>
                                  {etdDiffers ? etd : stop.departure}
                                </span>
                                {etdDiffers && (
                                  <span className="ml-1 text-[9px] text-muted line-through">sch {stop.departure}</span>
                                )}
                              </span>
                            )}
                          </div>
                          {isCur && (
                            <div className="mt-2.5 pt-2 border-t border-blue-500/20 flex items-center justify-start">
                              <LiveMovingTrainTrack
                                statusLabel={data?.speed && Number(data.speed) > 0 ? 'Live En Route' : 'Current Station'}
                                speedLabel={data?.speed ? `${data.speed} km/h` : null}
                              />
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  };

                  const renderSegmentedStops = (list: TimelineStop[], baseOffset: number) => {
                    const segments = groupTimelinePassThrough(list);
                    return segments.map((seg) => {
                      if (seg.kind === 'halt') {
                        return renderStop(seg.stop, baseOffset + seg.originalIndex);
                      }
                      const isExpanded = Boolean(expandedPassThrough[seg.id]);
                      return (
                        <div key={seg.id} className="pl-11 py-1">
                          <button
                            type="button"
                            onClick={() =>
                              setExpandedPassThrough((prev) => ({ ...prev, [seg.id]: !isExpanded }))
                            }
                            className="w-full flex items-center justify-between text-[11px] font-semibold text-muted hover:text-main bg-input/40 border border-subtle/60 rounded-xl px-3 py-1.5 transition-colors cursor-pointer"
                          >
                            <span>
                              {isExpanded ? 'Hide' : 'Show'} {seg.stops.length} pass-through stations
                            </span>
                            <ChevronDown className={`w-3.5 h-3.5 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                          </button>
                          {isExpanded && (
                            <div className="mt-1 space-y-1">
                              {seg.stops.map(({ stop, originalIndex }) =>
                                renderStop(stop, baseOffset + originalIndex)
                              )}
                            </div>
                          )}
                        </div>
                      );
                    });
                  };

                  return (
                    <div role="list" className="space-y-1">
                      {pastStops.length > 0 && (
                        <button
                          type="button"
                          onClick={() => setShowPastStops(prev => !prev)}
                          className="w-full mb-3 flex items-center justify-between text-xs text-muted font-bold py-2.5 px-4 rounded-xl border border-subtle bg-input hover:bg-strong transition-all"
                        >
                          <span>{showPastStops ? 'Hide' : 'View'} {pastStops.length} departed stops</span>
                          <ChevronDown className={`w-4 h-4 transition-transform ${showPastStops ? 'rotate-180' : ''}`} />
                        </button>
                      )}
                      {showPastStops && renderSegmentedStops(pastStops, 0)}
                      {renderSegmentedStops(activeStops, pastStops.length)}
                    </div>
                  );
                })()}
              </div>
              {/* Expand / Collapse toggle */}
              <button
                onClick={() => setShowAllStops(prev => !prev)}
                className="mt-4 w-full flex items-center justify-center gap-2 text-xs text-muted hover:text-main font-semibold py-2 rounded-xl border border-subtle hover:bg-card/50 transition-all"
              >
                {showAllStops ? (
                  <><ChevronUp className="w-3.5 h-3.5" /> Collapse to major stations</>
                ) : (
                  <><ChevronDown className="w-3.5 h-3.5" /> Show all {data.timeline.length} stops</>
                )}
              </button>
            </div>
          )}

          {/* Footer */}
          <div className="flex items-center justify-between text-xs text-muted px-1">
            <div className="flex items-center gap-1.5">
              <Zap className="w-3 h-3 text-blue-500" />
              Auto-refreshes every 30 seconds
            </div>
            {lastRefresh && <SecondsTicker since={lastRefresh} />}
          </div>

        </div>
      )}

      {/* Floating Jump to Current Station Button (only shown when scrolled away from current station) */}
      {!loading && showJumpFab && data?.timeline && data.timeline.length > 0 && (
        <button
          type="button"
          onClick={() => {
            const el = document.getElementById('current-train-stop');
            if (el) {
              el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
          }}
          aria-label="Jump to Current Station"
          className="fixed fab-safe-bottom right-4 sm:right-6 z-40 bg-blue-600 hover:bg-blue-700 active:scale-95 text-white font-bold text-[11px] sm:text-xs py-2.5 px-3.5 sm:py-3 sm:px-5 rounded-full shadow-2xl flex items-center gap-1.5 sm:gap-2 border border-blue-400 transition-all cursor-pointer touch-manipulation min-h-[44px]"
        >
          <Navigation size={14} className="text-white" />
          <span>Jump to Train</span>
        </button>
      )}

      <LimitReachedModal
        isOpen={showLimitModal}
        onClose={() => setShowLimitModal(false)}
        onRefresh={() => {
          setError(null);
          setQuotaBlocked(false);
          fetchLive(false, selectedDateRef.current);
        }}
      />
    </div>
  );
}
